// Pure rules of the public order: input validation and pricing. No I/O.
import { ApiError } from './http.ts';
import type { PublicServiceRow } from './public-order-store.ts';

/** Request body contract shared with apps/web (public-order-client.ts). */
export type PublicOrderStartPayload = {
  /** Random id generated by the browser: makes the call idempotent. */
  clientKey: string;
  customer: { name: string; phone: string; email?: string; notes?: string };
  whatsappOptIn: boolean;
  items: { serviceId: string; quantity: number; variantId?: string }[];
  /** What the customer saw. Never trusted: it only detects stale price lists. */
  expectedTotalCents?: number;
  /** Honeypot: real users never fill it. */
  website?: string;
};
export type PublicOrderTokenPayload = { token: string };

export const LIMITS = {
  maxServices: 10,
  maxQuantityPerService: 1000,
  nameMin: 2,
  nameMax: 80,
  emailMax: 120,
  notesMax: 500,
} as const;

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CLIENT_KEY = /^[A-Za-z0-9_-]{16,64}$/;
// Same shape the customers table accepts.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// eslint-disable-next-line no-control-regex -- reject ASCII control characters in free text.
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;

const invalid = (message: string, code = 'invalid_request') =>
  new ApiError(message, 400, code);

export type ParsedStart = {
  clientKey: string;
  name: string;
  phone: string;
  email: string | null;
  notes: string | null;
  whatsappOptIn: boolean;
  items: { serviceId: string; quantity: number; variantId?: string }[];
  expectedTotalCents: number | null;
};

function cleanText(
  value: unknown,
  label: string,
  max: number,
  options: { required: boolean; min?: number },
) {
  if (value === undefined || value === null || value === '') {
    if (options.required) throw invalid(`Completá ${label}.`);
    return null;
  }
  if (typeof value !== 'string' || CONTROL.test(value))
    throw invalid(`${label} no es válido.`);
  const text = value.replace(/\s+/g, ' ').trim();
  if (!text) {
    if (options.required) throw invalid(`Completá ${label}.`);
    return null;
  }
  if (text.length > max || text.length < (options.min ?? 1))
    throw invalid(`${label} no es válido.`);
  return text;
}

export function parseStartPayload(
  input: Partial<PublicOrderStartPayload>,
): ParsedStart {
  if (typeof input.website === 'string' && input.website.trim())
    throw invalid('La solicitud no es válida.');
  if (typeof input.clientKey !== 'string' || !CLIENT_KEY.test(input.clientKey))
    throw invalid('La solicitud no es válida.');
  const customer = input.customer;
  if (typeof customer !== 'object' || customer === null)
    throw invalid('Completá tus datos.');
  const name = cleanText(customer.name, 'Tu nombre', LIMITS.nameMax, {
    required: true,
    min: LIMITS.nameMin,
  })!;
  if (typeof customer.phone !== 'string')
    throw invalid('Completá tu número de WhatsApp.', 'invalid_phone');
  const email = cleanText(customer.email, 'El email', LIMITS.emailMax, {
    required: false,
  });
  if (email && !EMAIL.test(email)) throw invalid('El email no es válido.');
  const notes = cleanText(customer.notes, 'La nota', LIMITS.notesMax, {
    required: false,
  });
  if (typeof input.whatsappOptIn !== 'boolean')
    throw invalid('La solicitud no es válida.');
  if (
    !Array.isArray(input.items) ||
    input.items.length === 0 ||
    input.items.length > LIMITS.maxServices
  )
    throw invalid('Elegí al menos un tamaño.', 'invalid_items');
  const seen = new Set<string>();
  const items = input.items.map((item) => {
    if (
      typeof item !== 'object' ||
      item === null ||
      typeof item.serviceId !== 'string' ||
      !UUID.test(item.serviceId) ||
      !Number.isInteger(item.quantity) ||
      item.quantity < 1 ||
      item.quantity > LIMITS.maxQuantityPerService
    )
      throw invalid('Revisá las cantidades.', 'invalid_items');
    if (
      item.variantId !== undefined &&
      (typeof item.variantId !== 'string' || !UUID.test(item.variantId))
    )
      throw invalid('Revisá el tipo de papel.', 'invalid_items');
    const id = item.serviceId.toLowerCase();
    if (seen.has(id)) throw invalid('Revisá las cantidades.', 'invalid_items');
    seen.add(id);
    return {
      serviceId: id,
      quantity: item.quantity,
      variantId: item.variantId?.toLowerCase(),
    };
  });
  if (
    input.expectedTotalCents !== undefined &&
    (!Number.isSafeInteger(input.expectedTotalCents) ||
      input.expectedTotalCents < 0)
  )
    throw invalid('La solicitud no es válida.');
  return {
    clientKey: input.clientKey,
    name,
    phone: customer.phone,
    email,
    notes,
    whatsappOptIn: input.whatsappOptIn,
    items,
    expectedTotalCents: input.expectedTotalCents ?? null,
  };
}

export type PricedLine = {
  serviceId: string;
  name: string;
  quantity: number;
  unitPriceCents: number;
  totalCents: number;
  variantId?: string;
  photoServiceId?: string;
};

/**
 * The only place a price is computed. It reads the catalog row (never the request): the
 * order total is `sum(quantity × catalog price)`. A service that is not in the catalog
 * (inactive, not public, not orderable, other Business) is rejected, not silently dropped.
 */
export function priceOrder(
  catalog: PublicServiceRow[],
  items: { serviceId: string; quantity: number; variantId?: string }[],
) {
  const byId = new Map(catalog.map((service) => [service.id, service]));
  const lines: PricedLine[] = [];
  for (const item of items) {
    const service = byId.get(item.serviceId);
    if (!service)
      throw new ApiError(
        'Uno de los tamaños ya no está disponible. Actualizá la página.',
        409,
        'service_unavailable',
      );
    if (item.variantId && service.variant_id !== item.variantId)
      throw new ApiError(
        'El papel ya no está disponible.',
        409,
        'service_unavailable',
      );
    const tier = service.tiers?.find(
      (x) =>
        x.min_quantity <= item.quantity &&
        (x.max_quantity === null || x.max_quantity >= item.quantity),
    );
    if (service.tiers && !tier)
      throw new ApiError(
        'No hay precio disponible para esa cantidad de copias.',
        409,
        'service_unavailable',
      );
    const unitPriceCents = tier?.unit_price_cents ?? service.unit_price_cents;
    const totalCents = item.quantity * unitPriceCents;
    if (!Number.isSafeInteger(totalCents))
      throw invalid('Revisá las cantidades.', 'invalid_items');
    lines.push({
      serviceId: service.id,
      name: service.name,
      quantity: item.quantity,
      unitPriceCents,
      totalCents,
      variantId: item.variantId,
      photoServiceId: service.photo_service_id,
    });
  }
  const order = new Map(catalog.map((service, index) => [service.id, index]));
  lines.sort((a, b) => order.get(a.serviceId)! - order.get(b.serviceId)!);
  const totalCents = lines.reduce((sum, line) => sum + line.totalCents, 0);
  if (!Number.isSafeInteger(totalCents))
    throw invalid('Revisá las cantidades.', 'invalid_items');
  return { lines, totalCents };
}

/** Business rules raised by the SQL functions (`cc_error:<code>`) as safe API errors. */
export function orderRuleToApiError(code: string) {
  switch (code) {
    case 'price_changed':
      return new ApiError(
        'Los precios cambiaron. Revisá el total actualizado.',
        409,
        'price_changed',
      );
    case 'service_unavailable':
      return new ApiError(
        'Uno de los tamaños ya no está disponible. Actualizá la página.',
        409,
        'service_unavailable',
      );
    case 'invalid_phone':
      return new ApiError(
        'Revisá el número de WhatsApp.',
        422,
        'invalid_phone',
      );
    case 'uploads_pending':
      return new ApiError(
        'Esperá a que terminen todas las cargas antes de confirmar.',
        409,
        'uploads_pending',
      );
    case 'no_files':
      return new ApiError(
        'Todavía no hay fotos completas para confirmar el pedido.',
        409,
        'no_uploaded_files',
      );
    case 'order_not_found':
      return new ApiError('Link inválido.', 404, 'link_invalid');
    case 'too_many_links':
      return new ApiError(
        'Demasiados intentos. Probá más tarde.',
        429,
        'rate_limited',
      );
    case 'no_branch':
    case 'no_owner':
      return new ApiError(
        'Los pedidos online no están disponibles por el momento.',
        503,
        'orders_unavailable',
      );
    default:
      return invalid('La solicitud no es válida.');
  }
}
